<?php
if (!defined('ROUTER_LOADED')) { http_response_code(403); exit('Accès direct interdit.'); }
if (!userCan($user, 'caisse.rapport')) { http_response_code(403); echo '<div class="rounded-md border border-red-200 bg-red-50 p-4 text-red-700">Accès refusé.</div>'; return; }
require_once __DIR__ . '/../../api/database.php'; require_once __DIR__ . '/_finance.php';
$db=Database::getInstance();$role=$user['role_system'];[$from,$to,$month]=financeMonthRange((string)($_GET['mois']??date('Y-m')));
$sales=$db->fetch("SELECT COUNT(*) AS count,COALESCE(SUM(total_amount),0) AS total,COALESCE(SUM(netcash),0) AS collected,COALESCE(SUM(tva_paid),0) AS vat FROM sales WHERE status='Active' AND date BETWEEN ? AND ?",[$from,$to]);
$expenses=$db->fetch("SELECT COUNT(*) AS count,COALESCE(SUM(amount),0) AS total FROM expenses WHERE status='Active' AND date BETWEEN ? AND ?",[$from,$to]);
$cashIn=(float)$db->fetchColumn('SELECT COALESCE(SUM(amount),0) FROM cash_in WHERE date_created BETWEEN ? AND ?',[$from,$to]);
$cashOut=(float)$db->fetchColumn('SELECT COALESCE(SUM(amount),0) FROM cash_out WHERE created_at BETWEEN ? AND ?',[$from,$to]);
$debt=$db->fetch('SELECT COALESCE(SUM(GREATEST(COALESCE(amount,0)-COALESCE(paid_amount,0),0)),0) AS balance,COUNT(*) AS count FROM debts WHERE status IN (0,2)');
$byPayment=$db->fetchAll("SELECT payment_method,COUNT(*) AS count,COALESCE(SUM(total_amount),0) AS amount FROM sales WHERE status='Active' AND date BETWEEN ? AND ? GROUP BY payment_method ORDER BY amount DESC",[$from,$to]);
?>
<section class="space-y-5"><header><p class="text-sm font-semibold text-amber-800">Analyse financière</p><h1 class="mt-1 text-2xl font-bold text-slate-900">Rapports financiers</h1><p class="mt-1 text-sm text-slate-600">Synthèse des opérations du <?=financeEscape(date('d/m/Y',strtotime($from)))?> au <?=financeEscape(date('d/m/Y',strtotime($to)))?>.</p></header>
<form method="get" action="<?=financeEscape(app_url('router.php'))?>" class="flex flex-col gap-3 rounded-md border border-slate-200 bg-white p-4 sm:flex-row sm:items-end"><input type="hidden" name="route" value="<?=financeEscape($role.'/caisse/rapports')?>"><label class="space-y-1 text-sm font-medium">Mois<input type="month" name="mois" value="<?=financeEscape($month)?>" class="block rounded-md border border-slate-300 px-3 py-2 font-normal"></label><button class="rounded-md bg-green-700 px-4 py-2 text-sm font-semibold text-white">Afficher</button><a href="<?=financeEscape(app_route_url('caisse/transactions'))?>" class="px-3 py-2 text-sm font-medium text-green-800">Voir les transactions</a></form>
<div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><?php foreach([['Ventes enregistrées',number_format((float)$sales['total'],0,',',' ').' FBu','file-text','green'],['Net encaissé sur ventes',number_format((float)$sales['collected'],0,',',' ').' FBu','dollar-sign','blue'],['Dépenses',number_format((float)$expenses['total'],0,',',' ').' FBu','credit-card','rose'],['TVA collectée',number_format((float)$sales['vat'],0,',',' ').' FBu','percent','amber']] as [$label,$value,$icon,$color]):?><article class="flex items-start justify-between rounded-md border border-slate-200 bg-white p-5"><div><p class="text-sm text-slate-500"><?=financeEscape($label)?></p><p class="mt-2 text-xl font-bold text-slate-900"><?=financeEscape($value)?></p></div><i data-feather="<?=financeEscape($icon)?>" class="h-5 w-5 text-<?=financeEscape($color)?>-700"></i></article><?php endforeach;?></div>
<div class="grid gap-5 xl:grid-cols-2"><section class="overflow-hidden rounded-md border border-slate-200 bg-white"><div class="border-b px-5 py-4"><h2 class="font-semibold">Ventes par moyen de paiement</h2><p class="mt-1 text-sm text-slate-500"><?=number_format((int)$sales['count'],0,',',' ')?> opérations</p></div><table class="min-w-full divide-y text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-5 py-3">Moyen</th><th class="px-5 py-3 text-right">Opérations</th><th class="px-5 py-3 text-right">Montant</th></tr></thead><tbody class="divide-y"><?php if(!$byPayment):?><tr><td colspan="3" class="px-5 py-8 text-center text-slate-500">Aucune vente pour cette période.</td></tr><?php else:foreach($byPayment as $row):?><tr><td class="px-5 py-3"><?=financeEscape($row['payment_method']?:'Non précisé')?></td><td class="px-5 py-3 text-right"><?=number_format((int)$row['count'],0,',',' ')?></td><td class="px-5 py-3 text-right font-semibold"><?=number_format((float)$row['amount'],0,',',' ')?> FBu</td></tr><?php endforeach;endif;?></tbody></table></section>
<section class="space-y-4 rounded-md border border-slate-200 bg-white p-5"><h2 class="font-semibold">Situation financière</h2><dl class="space-y-3 text-sm"><div class="flex justify-between"><dt class="text-slate-500">Entrées manuelles</dt><dd class="font-semibold text-green-800">+<?=number_format($cashIn,0,',',' ')?> FBu</dd></div><div class="flex justify-between"><dt class="text-slate-500">Sorties de caisse</dt><dd class="font-semibold text-rose-700">−<?=number_format($cashOut,0,',',' ')?> FBu</dd></div><div class="flex justify-between"><dt class="text-slate-500">Dépenses comptabilisées</dt><dd class="font-semibold text-rose-700">−<?=number_format((float)$expenses['total'],0,',',' ')?> FBu</dd></div><div class="flex justify-between border-t pt-3"><dt class="font-semibold">Créances clients restantes</dt><dd class="font-bold"><?=number_format((float)$debt['balance'],0,',',' ')?> FBu</dd></div><p class="text-xs text-slate-500"><?=number_format((int)$debt['count'],0,',',' ')?> créance(s) ouvertes, toutes périodes confondues.</p></dl><p class="border-t pt-3 text-xs text-slate-500">Les ventes et dépenses utilisent leur statut actif; les sorties de caisse et dépenses sont présentées séparément.</p></section></div></section>